import javax.xml.bind.JAXBContext

class Bad {
    fun marshal(obj: Any): String {
        val ctx = JAXBContext.newInstance(obj::class.java) // bad: recreated per call
        return ctx.createMarshaller().run { java.io.StringWriter().also { marshal(obj, it) }.toString() }
    }
}

import javax.xml.bind.JAXBContext

fun marshalAll(items: List<Any>): List<String> =
    items.map {
        JAXBContext.newInstance(it::class.java) // bad: recreated per element
            .createMarshaller()
            .run { java.io.StringWriter().also { w -> marshal(it, w) }.toString() }
    }

import javax.xml.bind.JAXBContext

class GoodCompanion {
    companion object {
        private val CTX = JAXBContext.newInstance(GoodCompanion::class.java) // ok: created once
    }
    fun marshal(obj: Any): String =
        CTX.createMarshaller().run { java.io.StringWriter().also { marshal(obj, it) }.toString() }
}
